import type { KnowledgeCharacterId } from "@/server/domain/knowledge";

// Offline editorial proposals only. Facts are paraphrased from the corresponding
// Phase 1 excerpts, not added from biographies or generated by a runtime model.
// Each pair separates the main answer from its source-supported detail/caveat.
const proposals: Record<string, readonly [string, string]> = {
  "cmtt45-q001": ["Đó là cuộc cách mạng giải phóng dân tộc dưới sự lãnh đạo của Đảng Cộng sản Đông Dương và Hồ Chí Minh, với đông đảo nhân dân Việt Nam tham gia.", "Cuộc cách mạng đập tan ách thống trị của phát xít Nhật, lật đổ chế độ quân chủ và đưa chính quyền về tay nhân dân."],
  "cmtt45-q002": ["Thắng lợi dẫn đến sự ra đời của nước Việt Nam Dân chủ Cộng hòa ngày 2/9/1945.", "Việt Nam từ một nước thuộc địa, nửa phong kiến trở thành một nước độc lập; nhân dân từ thân phận nô lệ trở thành người làm chủ đất nước."],
  "cmtt45-q003": ["Ngày 15/8/1945, Nhật hoàng tuyên bố chấp nhận đầu hàng Đồng minh.", "Ngày 2/9/1945, Nhật Bản mới ký văn kiện đầu hàng chính thức. Cần phân biệt hai mốc này."],
  "cmtt45-q004": ["Nhật đảo chính Pháp ở Đông Dương ngày 9/3/1945.", "Nhật độc chiếm Đông Dương; tình hình chính trị, quân sự ở Việt Nam thay đổi nhanh chóng."],
  "cmtt45-q005": ["Ban Thường vụ Trung ương Đảng ban hành chỉ thị Nhật – Pháp bắn nhau và hành động của chúng ta ngày 12/3/1945.", "Chỉ thị xác định phát xít Nhật là kẻ thù chính, phát động cao trào kháng Nhật cứu nước và chuẩn bị tiến tới tổng khởi nghĩa."],
  "cmtt45-q006": ["Mâu thuẫn nổi bật là giữa toàn thể dân tộc Việt Nam với các thế lực đế quốc, phát xít xâm lược.", "Nhiệm vụ cấp bách hàng đầu là giải phóng dân tộc, giành độc lập và lập chính quyền của nhân dân. Từ đó, Đảng tập hợp lực lượng yêu nước thuộc nhiều giai cấp, tầng lớp và khuynh hướng chính trị."],
  "cmtt45-q007": ["Hội nghị Trung ương tháng 11/1939 xác định giải phóng dân tộc là nhiệm vụ quan trọng hàng đầu.", "Tư liệu đặt nhiệm vụ ấy trong tình hình mới lúc bấy giờ."],
  "cmtt45-q008": ["Nguyễn Ái Quốc trở về nước ngày 28/1/1941.", "Tư liệu gắn mốc này với việc trực tiếp lãnh đạo cách mạng trong nước."],
  "cmtt45-q009": ["Hội nghị Trung ương lần thứ 8, tháng 5/1941, hoàn chỉnh chủ trương chuyển hướng chiến lược, đặt giải phóng dân tộc lên trên hết và thành lập Việt Minh.", "Việt Minh tập hợp đông đảo các tầng lớp nhân dân đấu tranh giành độc lập."],
  "cmtt45-q010": ["Võ Nguyên Giáp trực tiếp tổ chức và chỉ huy Đội Việt Nam Tuyên truyền Giải phóng quân theo chỉ thị của Hồ Chí Minh.", "Đội được thành lập ngày 22/12/1944 và là một trong những lực lượng tiền thân quan trọng của Quân đội nhân dân Việt Nam."],
  "cmtt45-q011": ["Cao trào có hoạt động tuyên truyền, vận động chống Nhật; phát triển lực lượng chính trị và vũ trang; phá kho thóc để giải quyết nạn đói, thu hút quần chúng.", "Các khu căn cứ được mở rộng, lực lượng được chuẩn bị cho tổng khởi nghĩa và các cuộc khởi nghĩa từng phần diễn ra ở nơi có điều kiện thuận lợi."],
  "cmtt45-q012": ["Khu giải phóng Việt Bắc được thành lập ngày 4/6/1945.", "Trước đó, lực lượng cách mạng ở Việt Bắc phát triển mạnh trong tháng 5/1945. Khu giải phóng trở thành căn cứ địa quan trọng của tổng khởi nghĩa."],
  "cmtt45-q013": ["Sau tuyên bố đầu hàng của Nhật ngày 15/8/1945, bộ máy thống trị Nhật ở Đông Dương hoang mang, mất phương hướng; chính quyền thân Nhật không đủ khả năng kiểm soát tình hình.", "Đó là thời cơ đặc biệt thuận lợi để nhân dân giành chính quyền trước khi quân Đồng minh tiến vào Đông Dương."],
  "cmtt45-q014": ["Ủy ban Khởi nghĩa toàn quốc ban bố Quân lệnh số 1 vào đêm 13/8/1945, phát động Tổng khởi nghĩa.", "Ủy ban được thành lập ngày 13/8, trước khi tin Nhật đầu hàng được công bố rộng rãi."],
  "cmtt45-q015": ["Hội nghị toàn quốc của Đảng tại Tân Trào quyết định phát động toàn dân tổng khởi nghĩa.", "Hội nghị diễn ra từ ngày 14 đến 15/8/1945."],
  "cmtt45-q016": ["Quốc dân Đại hội tại Tân Trào tán thành chủ trương tổng khởi nghĩa, thông qua những chính sách lớn của Việt Minh và cử Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch.", "Đại hội họp ngày 16–17/8/1945."],
  "cmtt45-q017": ["Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi ngày 19/8/1945.", "Quần chúng tập hợp đông đảo, biểu tình và chiếm các cơ quan đầu não của chính quyền thân Nhật. Thắng lợi tác động mạnh đến phong trào cả nước."],
  "cmtt45-q018": ["Khởi nghĩa giành chính quyền ở Huế thắng lợi ngày 23/8/1945.", "Nhân dân và lực lượng cách mạng giành chính quyền tại kinh đô Huế, đánh dấu sự sụp đổ trên thực tế của triều đình nhà Nguyễn trong tiến trình cách mạng."],
  "cmtt45-q019": ["Khởi nghĩa giành chính quyền ở Sài Gòn thắng lợi ngày 25/8/1945.", "Thắng lợi tạo điều kiện cho phong trào ở nhiều tỉnh Nam Bộ và việc hoàn tất giành chính quyền trên cả nước."],
  "cmtt45-q020": ["Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, Hà Nội.", "Sự kiện tuyên bố thành lập nước Việt Nam Dân chủ Cộng hòa."],
  "cmtt45-q021": ["Diễn biến nổi bật ở sự nhanh chóng, phạm vi cả ba miền và việc kết hợp biểu tình chính trị, vận động quần chúng với lực lượng vũ trang khi cần thiết.", "Lực lượng cách mạng chủ động nắm thời cơ; sự tham gia đông đảo của nhân dân là nền tảng tạo nên thắng lợi tại nhiều địa phương."],
  "cmtt45-q022": ["Trường Chinh cùng Trung ương hoạch định đường lối, chuẩn bị khởi nghĩa; chủ trì hội nghị sau đảo chính Nhật – Pháp, góp phần hình thành chỉ thị ngày 12/3/1945.", "Đồng chí phụ trách Ủy ban Khởi nghĩa toàn quốc, đồng thời góp phần truyền đạt đường lối qua hoạt động tư tưởng, lý luận. Tư liệu nhấn mạnh vai trò lãnh đạo chính trị, tham mưu chiến lược và tổ chức chỉ đạo tổng khởi nghĩa."],
  "cmtt45-q023": ["Theo phần đính chính của tài liệu, Lê Duẩn bị bắt năm 1940, bị đày ra Côn Đảo và chỉ được đón về đất liền sau khi Cách mạng tháng Tám thành công.", "Không nên trình bày đồng chí trực tiếp chỉ đạo khởi nghĩa Nam Bộ trong tháng 8/1945. Đóng góp cần đặt trong hoạt động trước đó và lãnh đạo kháng chiến ở Nam Bộ sau cách mạng."],
  "cmtt45-q024": ["Phạm Văn Đồng tham gia công tác chính trị, tổ chức; được bầu vào Ủy ban Dân tộc giải phóng Việt Nam tại Quốc dân Đại hội tháng 8/1945 và là một trong năm thành viên Ban Thường trực.", "Sau thắng lợi, đồng chí giữ chức Bộ trưởng Bộ Tài chính trong Chính phủ lâm thời, góp phần giải quyết nhiệm vụ cấp bách và củng cố chính quyền mới."],
  "cmtt45-q025": ["Võ Nguyên Giáp tổ chức, chỉ huy Đội Việt Nam Tuyên truyền Giải phóng quân theo chỉ thị của Hồ Chí Minh; tham gia xây dựng lực lượng, đào tạo cán bộ, phát triển căn cứ và chỉ đạo quân sự trong cao trào kháng Nhật.", "Ngày 16/8/1945 tại Tân Trào, đồng chí đọc Quân lệnh số 1 rồi chỉ huy lực lượng tiến về giải phóng Thái Nguyên. Tổng khởi nghĩa là cuộc nổi dậy chính trị rộng lớn của quần chúng, có lực lượng vũ trang làm nòng cốt và hỗ trợ, không chỉ là một chiến dịch quân sự."],
  "cmtt45-q026": ["Võ Nguyên Giáp đọc Quân lệnh số 1 ngày 16/8/1945 tại Tân Trào, thay mặt Ủy ban Quân sự cách mạng.", "Đồng chí chỉ huy lực lượng tiến về giải phóng Thái Nguyên."],
  "cmtt45-q027": ["Bốn đồng chí có đóng góp ở những lĩnh vực khác nhau.", "Cần đặt những đóng góp ấy trong quan hệ với sự lãnh đạo chung của Đảng, Hồ Chí Minh, Việt Minh và sức mạnh quần chúng nhân dân."],
  "cmtt45-q028": ["Cách mạng lật đổ chính quyền thân Nhật, chấm dứt sự thống trị của phát xít Nhật và chế độ quân chủ; thiết lập chính quyền cách mạng cả nước, dẫn tới sự thành lập nước Việt Nam Dân chủ Cộng hòa ngày 2/9/1945.", "Giành chính quyền và tuyên bố độc lập chưa có nghĩa là hết thử thách: nền độc lập vẫn phải được bảo vệ trước âm mưu tái chiếm thuộc địa và các thế lực chống phá."],
  "cmtt45-q029": ["Đối với Việt Nam, cách mạng mở ra kỷ nguyên độc lập dân tộc, khẳng định sức mạnh quần chúng và tạo cơ sở xây dựng nhà nước mới.", "Thắng lợi còn tạo tiền đề cho đấu tranh bảo vệ độc lập. Sau tháng 8/1945, nhân dân tiếp tục chống thực dân Pháp quay trở lại, bảo vệ chính quyền và thành quả cách mạng."],
  "cmtt45-q030": ["Cách mạng cổ vũ phong trào giải phóng dân tộc ở các nước thuộc địa và phụ thuộc.", "Thắng lợi góp phần vào làn sóng tan rã của hệ thống thuộc địa cũ sau Chiến tranh thế giới thứ hai, khẳng định quyền tự quyết và khát vọng độc lập của các dân tộc bị áp bức."],
  "cmtt45-q031": ["Các nguyên nhân chủ quan gồm sự lãnh đạo của Đảng và Hồ Chí Minh, quá trình chuẩn bị lâu dài cùng sức mạnh đại đoàn kết dân tộc.", "Tư liệu còn nhấn mạnh tinh thần yêu nước, ý chí đấu tranh của nhân dân và khả năng chủ động nhận định, chớp thời cơ."],
  "cmtt45-q032": ["Các điều kiện khách quan là Chiến tranh thế giới thứ hai đi đến kết thúc, Nhật thất bại và đầu hàng, bộ máy thống trị Nhật ở Đông Dương suy yếu.", "Quân Đồng minh chưa kịp vào Đông Dương giải giáp quân Nhật, tạo khoảng thời gian thuận lợi để lực lượng cách mạng giành chính quyền."],
  "cmtt45-q033": ["Thời cơ quốc tế rất quan trọng nhưng không tự tạo ra thắng lợi: phải có lực lượng được chuẩn bị, đường lối, tổ chức lãnh đạo và quần chúng tham gia.", "Ngược lại, chuẩn bị lâu dài cần gắn với đánh giá chính xác tình hình và hành động đúng lúc mới chuyển thành thắng lợi quyết định."],
  "cmtt45-q034": ["Bài học là không chỉ trông chờ thời cơ nhất thời.", "Tổ chức, lực lượng chính trị và vũ trang, cơ sở quần chúng cùng phương án hành động cần được chuẩn bị từ trước."],
  "cmtt45-q035": ["Thời cơ thường chỉ xuất hiện trong thời gian ngắn.", "Vì vậy, đánh giá tình hình chính xác, quyết định kịp thời và tổ chức thực hiện thống nhất có ý nghĩa quyết định."],
  "cmtt45-q036": ["Đấu tranh chính trị của quần chúng có vai trò rất quan trọng trong việc làm tê liệt và thay thế chính quyền cũ.", "Lực lượng vũ trang hỗ trợ, bảo vệ và tạo điều kiện để phong trào giành thắng lợi."],
  "cmtt45-q037": ["Cách mạng tháng Tám là quá trình tổng khởi nghĩa giành chính quyền.", "Ngày 2/9/1945 là ngày Hồ Chí Minh công bố Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Hai nội dung không phải cùng một sự kiện."],
  "cmtt45-q038": ["Không thể đồng nhất vì Trường Chinh gắn với lãnh đạo chính trị, chỉ đạo tổng khởi nghĩa; Phạm Văn Đồng tham gia cơ quan lãnh đạo và xây dựng chính quyền; Võ Nguyên Giáp gắn với tổ chức lực lượng vũ trang.", "Lê Duẩn bị giam đến khi cách mạng thành công, sau đó về đất liền và tham gia kháng chiến ở Nam Bộ. Cần giữ đúng sự khác biệt này."],
  "cmtt45-q039": ["Tài liệu kết luận thắng lợi là sự kết hợp hoàn cảnh quốc tế thuận lợi, chuẩn bị lâu dài, lãnh đạo của Đảng và Hồ Chí Minh cùng sức mạnh quần chúng; bốn đồng chí có đóng góp khác nhau, trong đó Lê Duẩn về đất liền sau khi cách mạng thành công.", "Bài học xuyên suốt là kết hợp thời cơ với thực lực, đường lối phù hợp, tổ chức lãnh đạo hiệu quả và đoàn kết nhân dân."],
  "cmtt45-q040": ["Bảng tổng hợp ghi trọng tâm đóng góp của Võ Nguyên Giáp là xây dựng lực lượng vũ trang, tổ chức và thực hiện nhiệm vụ quân sự.", "Điểm cần nhớ gắn với Đội Việt Nam Tuyên truyền Giải phóng quân và nhiệm vụ khởi nghĩa."],
};

export function proposeCharacterDialogue(questionId: string): Record<KnowledgeCharacterId, string> {
  const pair = proposals[questionId];
  if (!pair) throw new Error(`Chưa có đề xuất lời thoại cho ${questionId}.`);
  const [main, detail] = pair;
  const variant = Number(questionId.slice(-3)) % 3;
  // Different teaching rhythms; no impersonated memories, invented quotes or facts.
  return {
    "truong-chinh": [
      `Cháu tách câu trả lời thành hai ý cho rõ nhé.\n1. ${main}\n2. ${detail}`,
      `Ta xét từng ý, cháu nhé. Trước hết: ${main}\nĐể hiểu đầy đủ, cần giữ thêm ý này: ${detail}`,
      `Cháu có thể sắp xếp câu trả lời như sau.\nÝ chính: ${main}\nPhần làm rõ: ${detail}`,
    ][variant],
    "le-duan": [
      `Cháu nhớ điểm chính này nhé: ${main}\n${detail}\nNắm chắc cả hai ý thì cháu sẽ không bỏ sót phần quan trọng của câu chuyện.`,
      `${main}\nĐó là điều cháu cần nắm chắc. Nhưng đừng bỏ qua phần còn lại nhé: ${detail}`,
      `Ta cùng nắm cho chắc câu này nhé, cháu. ${main}\n${detail}\nCháu thử nhắc lại bằng lời của mình để nhớ lâu hơn nhé!`,
    ][variant],
    "pham-van-dong": [
      `Để dễ hiểu, ta cùng bắt đầu từ câu trả lời ngắn nhé. ${main}\nCháu đọc thêm phần này để hiểu đầy đủ hơn: ${detail}`,
      `Ta cùng đọc chậm từng phần nhé, cháu. ${main}\nTài liệu còn giải thích thêm: ${detail}`,
      `${main}\nCháu có thể bắt đầu bằng ý đó. Rồi mình cùng xem thêm một chút nhé: ${detail}`,
    ][variant],
    "vo-nguyen-giap": [
      `Ta cùng ghi lại điều cần nhớ, cháu nhé.\n• ${main}\nĐối chiếu thêm với tư liệu:\n• ${detail}`,
      `Cháu nhớ chắc điểm này: ${main}\nĐọc kèm chi tiết trong tư liệu để tránh nhầm: ${detail}`,
      `Ta ghi ngắn gọn để cháu dễ ôn lại nhé.\n• ${main}\n• ${detail}\nKhi ôn, cháu đối chiếu đủ hai ý này với tài liệu.`,
    ][variant],
  };
}
